import{_ as s,y as o,a,o as i,a2 as r,D as n}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Omnibus Price Disclosure","description":"","frontmatter":{},"headers":[],"relativePath":"configure/omnibus.md","filePath":"configure/omnibus.md","lastUpdated":1789441803000}'),c={name:"configure/omnibus.md"};function h(l,e,p,d,u,m){const t=o("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=r('<h1 id="omnibus-price-disclosure" tabindex="-1">Omnibus Price Disclosure <a class="header-anchor" href="#omnibus-price-disclosure" aria-label="Permalink to &quot;Omnibus Price Disclosure&quot;">​</a></h1><p>The EU Omnibus Directive requires a store that announces a price reduction to show the lowest price it charged for that product in the 30 days before the reduction. Bagisto can record product prices over time and show that lowest price with a discounted price on the product page.</p><h2 id="turn-on-price-disclosure" tabindex="-1">Turn on price disclosure <a class="header-anchor" href="#turn-on-price-disclosure" aria-label="Permalink to &quot;Turn on price disclosure&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Omnibus Price Disclosure</strong>, switch <strong>Enable Omnibus Disclosure</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),n(t,{src:"/images/configure/products-omnibus.png",alt:"Omnibus Price Disclosure section of the Products screen with Enable Omnibus Disclosure switched on"}),e[1]||(e[1]=r('<p>The setting is per channel, so turn it on for each channel that sells to consumers in the EU.</p><h2 id="what-shoppers-see" tabindex="-1">What shoppers see <a class="header-anchor" href="#what-shoppers-see" aria-label="Permalink to &quot;What shoppers see&quot;">​</a></h2><p>When a product is sold below its regular price, for example through a special price, a catalog rule or a customer group price, the product page shows a line under the price:</p><p><strong>Lowest price 30 days prior to the discount:</strong> followed by that price.</p><p>The line appears only when the product has a discount and prices have been recorded for it. The lowest price is taken from the prices recorded in the last 30 days. When a special price has a start date, prices recorded on or after the start date are left out.</p><h2 id="where-the-prices-come-from" tabindex="-1">Where the prices come from <a class="header-anchor" href="#where-the-prices-come-from" aria-label="Permalink to &quot;Where the prices come from&quot;">​</a></h2><p>While the setting is on for a channel, the store records each product&#39;s price in every currency of that channel whenever the price changes. It checks every fifteen minutes, and also when a product is saved. Prices are kept for 35 days, so the 30-day comparison is always complete.</p><p>The recording and the daily clean-up run on the server&#39;s scheduler. If the line never appears on a channel that has been enabled for more than a day, ask whoever manages your server to check that the scheduler is running. A newly enabled channel has no history yet, and its first prices are recorded on the next scheduled run. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>Bagisto 2.4 doesn&#39;t have Omnibus price disclosure.</p>',10))])}const b=s(c,[["render",h]]);export{g as __pageData,b as default};
